<script lang="ts">
 import type {Project} from './model';import {displayDate} from './date-format';import {translator} from './i18n';
 export let project:Project;export let batchId:string;
 $:t=translator(project.settings.language);
 $:batch=project.payment_batches.find(b=>b.id===batchId);
 $:rows=(batch?.rows||[]).flatMap(row=>{const payment=project.payments.find(p=>p.id===row.payment_id),shares=row.historical_shares||(payment?project.service_accounting.payments.filter(s=>s.payment_id===row.payment_id):[]);const account=project.accounts.find(a=>a.id===row.account_id);return shares.map(share=>({date:payment?.payment_date||batch!.date,correction:row.amount.startsWith('-'),account:account?.number||'',service:project.services.find(s=>s.id===share.service_id)?.name[project.settings.language]||share.service_id,amount:share.amount,payment:payment?.id||'—'}));});
</script>
<div class="movements"><h3>{t('Взаиморасчёты с потребителями','Decontări cu consumatorii')}</h3><div class="table-wrap"><table><thead><tr><th>{t('Дата','Data')}</th><th>{t('Вид операции','Operațiune')}</th><th>{t('Лицевой счёт','Cont personal')}</th><th>{t('Услуга','Serviciu')}</th><th>{t('Сумма','Sumă')}</th><th>{t('Идентификатор платежа','Identificator plată')}</th></tr></thead><tbody>{#each rows as row}<tr><td>{displayDate(row.date,project)}</td><td>{row.correction?t('Корректировка','Ajustare'):t('Оплата','Plată')}</td><td>{row.account}</td><td>{row.service}</td><td>{row.amount}</td><td>{row.payment}</td></tr>{/each}</tbody></table></div>{#if !rows.length}<p>{t('Движений нет. Черновик не изменяет взаиморасчёты.','Nu există înregistrări. Ciorna nu modifică decontările.')}</p>{/if}</div>
<style>.movements{padding:14px}table{width:100%;border-collapse:collapse}th,td{padding:8px;text-align:left}th{background:#80808018}td:nth-child(5){text-align:right}</style>
